/* @autogenerated */
import { Component, signal } from '@angular/core';
import { TestBed } from '@angular/core/testing';
import { ListViewIconComponent } from './list-view-icon.component';

@Component({
  imports: [ListViewIconComponent],
  template: `<list-view-icon [counter]="counter()">
    <b class="main">M</b>
    <span listViewBadge>
      @if (verified()) {
        <img class="badge-image" alt="" />
      }
    </span>
  </list-view-icon>`,
})
class HostComponent {
  counter = signal<number | string | null>(null);
  verified = signal(false);
}

describe('ListViewIconComponent', () => {
  function create() {
    TestBed.configureTestingModule({ imports: [HostComponent] });
    const fixture = TestBed.createComponent(HostComponent);
    fixture.detectChanges();
    return fixture;
  }

  const counterOf = (element: HTMLElement) => element.querySelector('.list-view-icon-counter')?.textContent?.trim();

  it('shows the counter only for numbers greater than zero', () => {
    const fixture = create();
    expect(counterOf(fixture.nativeElement)).toBeUndefined();
    for (const empty of [0, -2, 'abc'] as const) {
      fixture.componentInstance.counter.set(empty);
      fixture.detectChanges();
      expect(counterOf(fixture.nativeElement)).toBeUndefined();
    }
    fixture.componentInstance.counter.set(3);
    fixture.detectChanges();
    expect(counterOf(fixture.nativeElement)).toBe('3');
    fixture.componentInstance.counter.set('120');
    fixture.detectChanges();
    expect(counterOf(fixture.nativeElement)).toBe('99+');
  });

  it('projects the main icon and the badge in its corner', () => {
    const fixture = create();
    const element: HTMLElement = fixture.nativeElement;
    expect(element.querySelector('list-view-icon > .main')).not.toBeNull();
    const badge = element.querySelector('.list-view-icon-badge') as HTMLElement;
    expect(getComputedStyle(badge).display).toBe('none');
    fixture.componentInstance.verified.set(true);
    fixture.detectChanges();
    expect(badge.querySelector('.badge-image')).not.toBeNull();
    expect(getComputedStyle(badge).display).toBe('flex');
  });
});
